 const terrain=new THREE.Mesh(new THREE.PlaneGeometry(180,180),ski?snow:finish('#ad9876'));terrain.rotation.x=-Math.PI/2;terrain.position.y=-.36;terrain.userData.rusticGround=true;upper.add(terrain);
 let active=false,overview=false;return {sides,ends,wallMap,setVisible(on,over=false){active=on;overview=over;sides.visible=on;upper.visible=!over;for(const e of ends)e.visible=on&&!over;},setEndView(side){for(const roof of rafters)roof.visible=active&&!overview&&roof.userData.trussZ*side<2;},update(){}};
